namespace Agent.Plugins.Helpers;

public class IcmPostTemplates
{
    //If need svg to base64 converter, please refer https://stackoverflow.com/questions/28450471/convert-inline-svg-to-base64-string
    private const string LogoBase64 = "data:image/svg+xml;base64,";
    private const string DiscussionEntryTemplate = $"<div style='border: 1px solid #C9CACB80;padding: 15px;padding-top: 0px;font-family: Arial, sans-serif;'><div style='background-color: rgba(0, 120, 212, 1);color: rgba(255, 255, 255, 1);font-weight: bold;padding: 4px 12px;font-size: 14px;display: inline-flex;margin;margin: 0px -15px 10px;'><img src='{LogoBase64}' alt='Azure SRE Agent Logo' style='height: 16px; width: auto; margin-right: 6px'>Azure SRE Agent</div><br><br>POST_CONTENT_HERE</div>";

    public static string GenerateDiscussionEntryByTemplate(string postContent, string? agentName)
    {
        if (!string.IsNullOrWhiteSpace(agentName))
        {
            postContent = postContent + $"<br /><br />Agent Name: {agentName}";
        }
        return DiscussionEntryTemplate.Replace("POST_CONTENT_HERE", postContent);
    }
}
